import json,sys,re
raw=sys.stdin.read()
try:
    data=json.loads(raw) if raw.strip() else {}
except Exception:
    data={}
cmd=(data.get('tool_input') or data.get('input') or {})
if isinstance(cmd, dict):
    c=cmd.get('command') or cmd.get('cmd') or ''
else:
    c=str(cmd)
# Fail open unless clear footgun; permission deny is primary. Block only extreme patterns.
blocked=[
    r'\brm\s+-rf\s+/(?!tmp|var/folders|Users/[^/]+/.*\.cache)',
    r'git\s+push\s+.*--force',
    r'git\s+push\s+-f\b',
    r'git\s+reset\s+--hard\b',
]
for pat in blocked:
    if re.search(pat, c):
        print(json.dumps({'decision':'deny','reason':f'Blocked by IndexedEx safety hook: matched {pat}'}))
        sys.exit(0)
print(json.dumps({'decision':'allow'}))
